class Solution { public: vector<vector<int>> spiralMatrixIII(int rows,int cols,int rStart,int cStart){vector<vector<int>> answer{{rStart,cStart}};int directions[4][2]={{0,1},{1,0},{0,-1},{-1,0}},direction=0,steps=1,row=rStart,column=cStart;while((int)answer.size()<rows*cols){for(int twice=0;twice<2;++twice){for(int move=0;move<steps;++move){row+=directions[direction][0];column+=directions[direction][1];if(row>=0&&row<rows&&column>=0&&column<cols)answer.push_back({row,column});}direction=(direction+1)%4;}++steps;}return answer;} };
